import java.util.*;
import java.io.*;

public class Main {
    static class Pair {
        int x, y;
        Pair(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    static final int MAXR = 11;
    static final int MAXN = 1000;
    static final int MAXM = 100100;
    static final int INF = 1 << 29;

    static int[] edges = new int[2 * MAXM];
    static int[] flowVal = new int[2 * MAXM];
    static int[] cap = new int[2 * MAXM];
    static int[] nxtEdge = new int[2 * MAXM];
    static int[] head = new int[MAXN + 1];
    static int[] cur = new int[MAXN + 1];
    static int[] dist = new int[MAXN + 1];
    static int[] qArr = new int[MAXN + 1];

    static int ECount, NNodes, S, T, frontIdx, rearIdx;

    static void initFlow(int nodes, int sNode, int tNode) {
        NNodes = nodes;
        S = sNode;
        T = tNode;
        ECount = 2;
        for (int i = 0; i <= NNodes; i++) {
            head[i] = 0;
        }
    }

    static void addEdge(int u, int v, int c) {
        edges[ECount] = v;
        flowVal[ECount] = 0;
        cap[ECount] = c;
        nxtEdge[ECount] = head[u];
        head[u] = ECount++;
        edges[ECount] = u;
        flowVal[ECount] = 0;
        cap[ECount] = 0;
        nxtEdge[ECount] = head[v];
        head[v] = ECount++;
    }

    static boolean buildLevel() {
        for (int i = 0; i <= NNodes; i++) dist[i] = 0;
        frontIdx = rearIdx = 0;
        qArr[frontIdx++] = S;
        dist[S] = 1;
        while (rearIdx < frontIdx && dist[T] == 0) {
            int u = qArr[rearIdx++];
            for (int e = head[u]; e != 0; e = nxtEdge[e]) {
                int v = edges[e];
                if (dist[v] == 0 && flowVal[e] < cap[e]) {
                    dist[v] = dist[u] + 1;
                    qArr[frontIdx++] = v;
                }
            }
        }
        return dist[T] != 0;
    }

    static int sendFlow(int u, int f) {
        if (u == T) return f;
        for (int e = cur[u], fSent = 0; e != 0; e = nxtEdge[e]) {
            int v = edges[e];
            if (dist[u] < dist[v] && flowVal[e] < cap[e] && (fSent = sendFlow(v, Math.min(f, cap[e] - flowVal[e])) ) > 0) {
                flowVal[e] += fSent;
                flowVal[e ^ 1] -= fSent;
                return fSent;
            }
        }
        return 0;
    }

    static int maxFlow() {
        int totalFlow = 0, f;
        while (buildLevel()) {
            for (int i = 0; i <= NNodes; i++) cur[i] = head[i];
            while ((f = sendFlow(S, INF)) > 0) totalFlow += f;
        }
        return totalFlow;
    }

    static int R, T;
    static String[] mazeA = new String[MAXR];
    static String[] mazeB = new String[MAXR];

    static int[] deltaX = {0, 1, 0, -1};
    static int[] deltaY = {1, 0, -1, 0};

    static boolean canProceed(int i, int j) {
        return (i >= 0 && j >= 0 && i < R && j < R && mazeA[i].charAt(j) != 'Y' && mazeA[i].charAt(j) != 'Z');
    }

    static int[][][] timeMap = new int[2][MAXR][MAXR];

    static void performBFS(int i, int j, int c) {
        for (int k = 0; k < R; k++) {
            for (int l = 0; l < R; l++) {
                timeMap[c][k][l] = 0;
            }
        }
        timeMap[c][i][j] = 1;
        Queue<Pair> q = new LinkedList<>();
        q.offer(new Pair(i, j));
        while (!q.isEmpty()) {
            Pair p = q.poll();
            int x = p.x;
            int y = p.y;
            if (c == 1 && (timeMap[0][x][y] != 0 && timeMap[0][x][y] <= timeMap[1][x][y])) continue;
            for (int k = 0; k < 4; k++) {
                int nx = x + deltaX[k];
                int ny = y + deltaY[k];
                if (canProceed(nx, ny) && timeMap[c][nx][ny] == 0) {
                    timeMap[c][nx][ny] = timeMap[c][x][y] + 1;
                    q.offer(new Pair(nx, ny));
                }
            }
        }
    }

    static int[][][] nodeIDMap = new int[2][MAXR][MAXR];

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        R = Integer.parseInt(st.nextToken());
        T = Integer.parseInt(st.nextToken());

        int zi = 0, zj = 0;
        int totalNodes = 0, start = 0, end = 0;

        for (int i = 0; i < R; i++) {
            mazeA[i] = br.readLine();
            for (int j = 0; j < R; j++) {
                if (mazeA[i].charAt(j) == 'Z') {
                    zi = i;
                    zj = j;
                } else if (mazeA[i].charAt(j) != 'Y') {
                    totalNodes++;
                    nodeIDMap[0][i][j] = totalNodes;
                }
            }
        }

        for (int i = 0; i < R; i++) {
            mazeB[i] = br.readLine();
            for (int j = 0; j < R; j++) {
                if (mazeB[i].charAt(j) != 'Y' && mazeB[i].charAt(j) != 'Z') {
                    totalNodes++;
                    nodeIDMap[1][i][j] = totalNodes;
                }
            }
        }

        totalNodes++;
        start = 0;
        end = totalNodes;
        initFlow(totalNodes, start, end);

        for (int i = 0; i < R; i++) {
            for (int j = 0; j < R; j++) {
                if (mazeA[i].charAt(j) != 'Z' && mazeA[i].charAt(j) != 'Y') {
                    addEdge(start, nodeIDMap[0][i][j], mazeA[i].charAt(j) - '0');
                    addEdge(nodeIDMap[1][i][j], end, mazeB[i].charAt(j) - '0');
                }
            }
        }

        performBFS(zi, zj, 0);

        for (int i = 0; i < R; i++) {
            for (int j = 0; j < R; j++) {
                if (mazeA[i].charAt(j) > '0' && mazeA[i].charAt(j) <= '9') {
                    performBFS(i, j, 1);
                    for (int ii = 0; ii < R; ii++) {
                        for (int jj = 0; jj < R; jj++) {
                            if (mazeB[ii].charAt(jj) > '0' && mazeB[ii].charAt(jj) <= '9') {
                                if (timeMap[1][ii][jj] != 0 && (timeMap[0][ii][jj] == 0 || timeMap[0][ii][jj] >= timeMap[1][ii][jj]) && timeMap[1][ii][jj] - 1 <= T) {
                                    addEdge(nodeIDMap[0][i][j], nodeIDMap[1][ii][jj], INF);
                                }
                            }
                        }
                    }
                }
            }
        }

        System.out.println(maxFlow());
    }
}
